args.script:
(() => {
  const selectors = ['article','[data-testid="tweet"]','div[data-testid="cellInnerDiv"]'];
  const results = {};
  for (const sel of selectors) {
    results[sel] = Array.from(document.querySelectorAll(sel)).slice(0,10).map((el,i)=>({i, text: el.innerText, aria: el.getAttribute('aria-label'), html: el.outerHTML.slice(0,500)}));
  }
  return results;
})()
